mapper.sql:
WHERE member_id = #{memberId}
  AND use_yn = 'Y'

    AND (diagram_title LIKE CONCAT('%', #{searchKeyword}, '%')
      OR diagram_description LIKE CONCAT('%', #{searchKeyword}, '%'))


    AND diagram_type = #{diagramType}

mapper.update:
UPDATE diagrams
   SET diagram_title = #{diagramTitle},
       diagram_description = #{diagramDescription},
       diagram_type = #{diagramType},
       diagram_model = #{diagramModel},
       version_number = version_number + 1
 WHERE diagram_id = #{diagramId}
   AND member_id = #{memberId}
   AND use_yn = 'Y'
   AND version_number = #{expectedVersionNumber}

UPDATE diagrams
   SET use_yn = 'N',
       deleted_at = NOW(6)
 WHERE diagram_id = #{diagramId}
   AND member_id = #{memberId}
   AND use_yn = 'Y'

mapper.delete:
DELETE FROM diagram_versions
 WHERE diagram_id = #{diagramId}
   AND version_number < (
       SELECT min_kept_version FROM (
           SELECT MIN(version_number) AS min_kept_version FROM (
               SELECT version_number
                 FROM diagram_versions
                WHERE diagram_id = #{diagramId}
                ORDER BY version_number DESC
                LIMIT #{keepCount}
           ) AS recent_versions
       ) AS kept_boundary
   )
